!function(e){function r(r){for(var n,a,p=r[0],m=r[1],d=r[2],c=0,y=[];c<p.length;c++)a=p[c],Object.prototype.hasOwnProperty.call(i,a)&&i[a]&&y.push(i[a][0]),i[a]=0;for(n in m)Object.prototype.hasOwnProperty.call(m,n)&&(e[n]=m[n]);for(s&&s(r);y.length;)y.shift()();return o.push.apply(o,d||[]),t()}function t(){for(var e,r=0;r<o.length;r++){for(var t,a=o[r],p=!0,m=1;m<a.length;m++)t=a[m],0!==i[t]&&(p=!1);p&&(o.splice(r--,1),e=n(n.s=a[0]))}return e}function n(r){if(a[r])return a[r].exports;var t=a[r]={i:r,l:!1,exports:{}};return e[r].call(t.exports,t,t.exports,n),t.l=!0,t.exports}var a={},i={61:0},o=[];n.m=e,n.c=a,n.d=function(e,r,t){n.o(e,r)||Object.defineProperty(e,r,{enumerable:!0,get:t})},n.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},n.t=function(e,r){if(1&r&&(e=n(e)),8&r)return e;if(4&r&&"object"==typeof e&&e&&e.__esModule)return e;var t=Object.create(null);if(n.r(t),Object.defineProperty(t,"default",{enumerable:!0,value:e}),2&r&&"string"!=typeof e)for(var a in e)n.d(t,a,function(r){return e[r]}.bind(null,a));return t},n.n=function(e){var r=e&&e.__esModule?function(){return e.default}:function(){return e};return n.d(r,"a",r),r},n.o=function(e,r){return Object.prototype.hasOwnProperty.call(e,r)},n.p="";var p=window.webpackJsonp=window.webpackJsonp||[],m=p.push.bind(p);p.push=r,p=p.slice();for(var d=0;d<p.length;d++)r(p[d]);var s=m;o.push([50,0]),t()}({50:function(e,r,t){"use strict";t.r(r);var n=t(0);Object(n.a)("de","army",t(51),t(1))},51:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"坦克歼击车","link":"de_army#de_army_tankdestroyer"}],"model":"“追猎者”坦克歼击车","description":"<p>“追猎者”坦克歼击车是在捷克产的38吨坦克底盘上加装75mm火炮改装而成的自行反坦克炮车。1944年4月完成首批20辆的制作，定型为Jagdpanzer 38（t） “HetZer”（追猎者），制式编号为Sdkfz 138/2；该车到1945年战争结束时一共生产了2584辆。</p><p>“追猎者”坦克歼击车虽然装甲厚度不大，但低矮的车身和倾斜的甲板为该车提供了良好的防御能力；车上配备的75mm火炮装能在炮架上旋转，一挺MG34机枪安装在车顶上；该车对原38吨坦克底盘的悬挂系统作了改进，发动机功率也得到增大，使车辆的可靠性得到提高；但是该车的战斗室空间过小，造成乘员活动空间和观察视角的不足，也影响了战斗力的发挥。该车结构简单，能迅速大量地制造，因此在一年多时间就生产了2千多辆。</p><p>追猎者”坦克歼击车在1944年5月正式服役，配备给德军各反坦克部队中，由于该车数量较多，在二战后期战场上对苏军与盟军的进攻也造成了一定的阻碍。但在苏军与盟军强大的炮火面前，它最终也是逃脱不了灭亡的命运。</p>","part1title":"","part1description":"","part1content":[{"image":"{{text}}“追猎者”坦克歼击车四视图{{image}}imgs/de/army/de_army_tankdestroyerhetzer_11.jpg","description":"<h6>“追猎者”坦克歼击车<br>型号：Jagdpanzer  38（t） “HetZer”（追猎者），制式编号：Sdkfz 138/2</h6><p>参数：车长：5.1m，车宽：2.63m，车高：2.17m，车重：15.75t；乘员：4人。</p><p>最高车速：42km/h，最大行程：177km；</p><p>装甲厚度：前装甲与驾驶室正面装甲：60mm，两侧装甲：20mm，车体后部装甲：8-20mm，车体顶部：8mm，车体底部：10mm。</p><p>武器配备：1门Pak39L/48型75mm 火炮；火炮高低射界为-6～+12度，方向射界为左5度右11度，炮弹基数为41发； </p><p>1挺MG34型7.92mm机枪，配备1200发子弹。</p>","caption":""}],"part2title":"战场上的“追猎者”坦克歼击车","part2description":"","part2content":[{"image":"imgs/de/army/de_army_tankdestroyerhetzer_21.jpg","description":"1944年8月波兰首都华沙，德军不明单位的一辆“追猎者”坦克歼击车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerhetzer_22.jpg","description":"1945年3月，波罗的海沿岸的波美拉尼亚地区，德国武装党卫军第11装甲掷弹兵师第11反坦克营的一辆“追猎者”坦克歼击车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerhetzer_23.jpg","description":"1945年5月，德国武装党卫军第20装甲掷弹兵师第20反坦克营的一辆“追猎者”坦克歼击车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerhetzer_24.jpg","description":"1944年在德国某武器试验场进行测试的一辆德军“追猎者”坦克歼击车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerhetzer_25.jpg","description":"1945年,西线战场，一辆被击毁的德军“追猎者”坦克歼击车，一名美军正在车旁观察该车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerhetzer_26.jpg","description":"1945年,西线战场，两辆德军“追猎者”坦克歼击车在防御阵地中被击毁，美军越过该阵地继续向前进攻。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerhetzer_27.jpg","description":"1945年3月，在Danzig地区，一辆被遗弃的德军不明单位的“追猎者”坦克歼击车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerhetzer_28.jpg","description":"1945年2月,匈牙利布达佩斯，一辆被苏军缴获的德军“追猎者”坦克歼击车，苏军在这辆车的车体上标注了115编号。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerhetzer_29.jpg","description":"1945年5月,德国柏林西部战场，被缴获的隶属德军“沙恩霍斯特”步兵师的一辆“追猎者”坦克歼击车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyerhetzer_30.jpg","description":"1945年4月,德国柏林战场，一辆作路障的德军“追猎者”坦克歼击车。","caption":""}]}')}});